<script setup lang="ts">
import { ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import { api, errorText } from '../services/api'
import type { Attempt } from '../types/api'
import StateNotice from '../components/StateNotice.vue'
import KnowledgeTable from '../components/KnowledgeTable.vue'
import EvidenceList from '../components/EvidenceList.vue'
const route = useRoute(), attempt = ref<Attempt | null>(null), loading = ref(true), error = ref('')
const percent = (value: number | null) => value === null ? '证据不足' : `${(value * 100).toFixed(0)}%`
const deltaText = (value: number | null) => value === null ? '无法比较' : `${value > 0 ? '+' : ''}${(value * 100).toFixed(0)} 个百分点`
function kpName(id: string) { return attempt.value?.report?.knowledge_points.find(kp => kp.knowledge_point_id === id)?.name ?? id }
async function load() { loading.value = true; error.value = ''; attempt.value = null; try { attempt.value = await api.attempt(String(route.params.attemptId)) } catch (e) { error.value = errorText(e) } finally { loading.value = false } }
watch(() => route.params.attemptId, load, { immediate: true })
</script>
<template><div class="page-heading"><p class="eyebrow">03 / 学习报告</p><h1>查看本次表现</h1></div><StateNotice :loading="loading" :error="error" @retry="load" /><template v-if="attempt && !error"><section class="card"><div class="report-top"><div><span class="muted">本次得分</span><p class="score">{{ attempt.score }} <small>/ {{ attempt.max_score }}</small></p><p>测验得分率 {{ attempt.percentage }}%</p></div><RouterLink class="button" :to="{ path: `/quiz/${attempt.course_id}`, query: { baseline: attempt.id } }">基于本次结果复测</RouterLink></div></section><section v-if="!attempt.report" class="card"><h2>{{ attempt.ai_status === 'processing' ? '报告准备中' : attempt.ai_status === 'disabled' ? '诊断功能未启用' : '诊断服务尚未可用' }}</h2><p>{{ attempt.ai_message || '成绩已保存，稍后可以从历史记录重新查看。' }}</p><p class="muted">当前仅展示本次测验成绩。知识点诊断、检索引用和学习推荐尚未返回。</p></section><template v-else><section class="card"><p class="hint">运行模式：{{ attempt.report.mode === 'rule_template_demo' ? '规则与模板演示' : attempt.report.mode }}</p><p v-if="attempt.report.fallback_status" class="hint">服务状态：{{ attempt.report.fallback_status }}</p><p class="explanation">{{ attempt.report.explanation }}</p></section><section class="card"><h2>知识点表现</h2><KnowledgeTable :items="attempt.report.knowledge_points" /></section><section class="card"><h2>复习建议</h2><p v-if="!attempt.report.recommendations.length" class="muted">本次未返回推荐内容，可继续练习以增加诊断证据。</p><article v-for="(item, index) in attempt.report.recommendations" :key="`${item.resource_id}-${index}`" class="list-item"><h3>{{ item.title }}</h3><p>{{ item.reason }}</p><p class="muted">知识点：{{ kpName(item.knowledge_point_id) }} · 资源编号：{{ item.resource_id }}</p></article></section><section class="card"><h2>报告引用与证据</h2><EvidenceList :items="attempt.report.evidence" /></section><section v-if="attempt.report.comparison.length" class="card"><h2>与基线测验比较</h2><div class="table-scroll"><table><thead><tr><th>知识点</th><th>基线正确率</th><th>本次正确率</th><th>变化</th></tr></thead><tbody><tr v-for="item in attempt.report.comparison" :key="item.knowledge_point_id"><td>{{ kpName(item.knowledge_point_id) }}</td><td>{{ percent(item.before_accuracy) }}</td><td>{{ percent(item.after_accuracy) }}</td><td>{{ deltaText(item.delta) }}</td></tr></tbody></table></div></section><section class="card"><h2>处理过程</h2><ul><li v-for="(item, index) in attempt.report.trace" :key="index">{{ item.agent }}：{{ item.status }}</li></ul></section></template></template></template>
